import { createContext, useContext, useEffect, type ReactNode } from 'react'
import { useShellStore } from '@/app/store/shellStore'
import type { TenantManifest } from '@/entities/tenant/types'
import { hexToHslTokens } from '@/shared/utils/color'

type ThemeContextValue = {
  manifest: TenantManifest | null
}

const ThemeContext = createContext<ThemeContextValue>({ manifest: null })

export function useTheme() {
  return useContext(ThemeContext)
}

type Props = {
  children: ReactNode
  manifest: TenantManifest | null
}

function applyTokens(tokens: Record<string, string>) {
  const root = document.documentElement
  const mapping: Record<string, string> = {
    background: '--background',
    foreground: '--foreground',
    surface: '--surface',
    border: '--border',
    muted: '--muted',
    mutedForeground: '--muted-foreground',
    primary: '--primary',
    primaryForeground: '--primary-foreground',
    accent: '--accent',
    accentForeground: '--accent-foreground',
    success: '--success',
    warning: '--warning',
    danger: '--danger',
    info: '--info',
    radius: '--radius',
  }
  Object.entries(mapping).forEach(([key, cssVar]) => {
    if (tokens[key]) root.style.setProperty(cssVar, tokens[key])
  })
}

export function ThemeProvider({ children, manifest }: Props) {
  const { themeMode, accentPreset, customAccent, gradientFrom, gradientTo } = useShellStore()

  useEffect(() => {
    const root = document.documentElement
    const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches
    const isDark = themeMode === 'dark' || (themeMode === 'system' && prefersDark)

    root.classList.toggle('dark', isDark)

    if (manifest) {
      const tokens = isDark ? manifest.branding.darkTheme : manifest.branding.lightTheme
      applyTokens(tokens as unknown as Record<string, string>)
    }

    root.classList.remove('accent-green', 'accent-blue', 'accent-purple', 'accent-orange', 'accent-rose')

    if (customAccent) {
      const hsl = hexToHslTokens(customAccent)
      if (hsl) {
        root.style.setProperty('--accent', hsl)
        root.style.setProperty('--accent-foreground', '210 40% 98%')
      }
    } else {
      root.style.removeProperty('--accent')
      root.style.removeProperty('--accent-foreground')
      root.classList.add(`accent-${accentPreset}`)
    }

    if (gradientFrom && gradientTo) {
      const gradient = `linear-gradient(135deg, ${gradientFrom}, ${gradientTo})`
      root.style.setProperty('--gradient-brand', gradient)
      root.style.setProperty('--gradient-brand-from', gradientFrom)
      root.style.setProperty('--gradient-brand-to', gradientTo)
    } else {
      root.style.removeProperty('--gradient-brand')
      root.style.removeProperty('--gradient-brand-from')
      root.style.removeProperty('--gradient-brand-to')
    }
  }, [themeMode, accentPreset, customAccent, gradientFrom, gradientTo, manifest])

  return <ThemeContext.Provider value={{ manifest }}>{children}</ThemeContext.Provider>
}
